#include <iostream>
#include <string>
#include <vector>

template <typename T>
T smallest(T a, T b) {
    return (a < b) ? a : b;
}

template <typename T>
T sumAll(const std::vector<T>& v) {
    T total{};
    for (const auto& x : v) {
        total += x;
    }
    return total;
}

int main() {
    const std::vector<int> points = {4, 5, 6};
    const std::vector<double> lengths = {1.5, 2.25};
    const std::vector<std::string> parts = {"ab", "cd", "ef"};
