#include <iomanip>
#include <iostream>
#include <numeric>
#include <string>
#include <type_traits>
#include <vector>

template <typename T>
void show(const T& value) {
    if constexpr (std::is_integral_v<T>) {
        std::cout << value << '\n';
    } else if constexpr (std::is_floating_point_v<T>) {
        std::cout << std::fixed << std::setprecision(2) << value << '\n';
    } else {
        std::cout << '[' << value << "]\n";
    }
}

template <typename T>
int total(const T& value) {
    if constexpr (std::is_integral_v<T>) {
        return value;
    } else {
        return std::accumulate(value.begin(), value.end(), 0);
    }
}

int main() {
    show(7);
    show(3.14159);
    show(std::string("hi"));
    std::cout << total(7) << '\n';
    std::cout << total(std::vector<int>{1, 2, 3}) << '\n';
    return 0;
}
